package notification.api;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import notification.api.dto.NotificationRequest;import notification.core.NotificationContext;import notification.orchestration.NotificationOrchestrator;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;/** * Manual send endpoint — mostly for testing. Real triggers come via Kafka * (UserRegisteredHandler, NotifyUserCommandHandler). */@Slf4j@RestController@RequestMapping("/api/v1/notifications")@RequiredArgsConstructorpublic class NotificationController {    private final NotificationOrchestrator orchestrator;    @PostMapping    public ResponseEntity<Void> send(@Valid @RequestBody NotificationRequest req) {        log.info("HTTP send request: type={} recipient={}", req.type(), req.recipient());        NotificationContext ctx = new NotificationContext();        ctx.setType(req.type());        ctx.setRecipient(req.recipient());        ctx.setMessage(req.message());        ctx.setMetadata(req.metadata());        orchestrator.orchestrate(ctx);        return ResponseEntity.status(HttpStatus.ACCEPTED).build();    }}